    val words: List<WeeklyVocabWord> = rawSeeds.mapIndexed { idx, s ->
        val session = when {
            idx < 67 -> 1
            idx < 134 -> 2
            else -> 3
        }
        WeeklyVocabWord(
            id = "w1_${(idx + 1).toString().padStart(3, '0')}",
            word = s.word,
            arabic = s.ar,
            meaning = s.meaning,
            storyLine = s.story,
            domain = s.domain,
            cefrLevel = s.level,
            sessionNumber = session
        )
    }
